<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { cn } from '../../utils.js'; import { formatContextTokens, useContextContext } from './context-state.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'class'> { class?: string; children?: Snippet<[number]>; } let { class: className = '', children, ...rest }: Props = $props(); const context = useContextContext('ContextOutputUsage'); const tokens = $derived(context.usage?.outputTokens ?? 0);</script>
{#if children || tokens}<div {...rest} class={cn('svadmin-ai-context-part__usage', className)} data-slot="context-output-usage">{#if children}{@render children(tokens)}{:else}<span>Output</span><strong>{formatContextTokens(tokens)}</strong>{/if}</div>{/if}
<style>.svadmin-ai-context-part__usage { display: flex; align-items: center; justify-content: space-between; gap: .75rem; font-size: .75rem; }.svadmin-ai-context-part__usage span { color: var(--muted-foreground, currentColor); }</style>
